{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="A membership-based series of guided sound gatherings and private sessions in {{CITY}}, {{STATE}}. Gentle sonic structures for clearer nights and steadier days.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="layout-asym">
  <header class="site-header">
    <div class="brand">
      <h1 class="brand-name">{{BUSINESS_NAME}}</h1>
      <p class="brand-tag">{{TAGLINE}}</p>
    </div>
    <nav class="main-nav">
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private Offerings</a>
      <a href="pricing.html">Plans</a>
      <a href="about.html">About</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
    <div class="cta-wrap">
      <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </div>
  </header>

  <main>
    <section class="hero" aria-label="intro">
      <div class="pattern-bg" aria-hidden="true"></div>
      <div class="hero-inner">
        <h2>Rest framed as an intentional practice</h2>
        <p class="lead">Join a membership model of curated acoustic sessions and private guidance designed to re-tune rest and recover clarity. Small cohorts, predictable rhythms, and clear takeaways.</p>
        <div class="hero-actions">
          <a class="btn" href="events.html">See upcoming gatherings</a>
          <a class="btn ghost" href="pricing.html">Explore plans</a>
        </div>
      </div>
    </section>

    <section class="story" id="why">
      <div class="container">
        <h3>What we make possible</h3>
        <p>We use sustained tones and guided transitions to create predictable, repeatable sessions that favor measurable calm. Each gathering is structured for entry, pause, and gentle return — tools you can apply between meetings.</p>
        <ul class="bullets">
          <li>Short-form practices for daily regulation</li>
          <li>Group sessions that encourage slowed attention</li>
          <li>Private workbooks and integrated follow-ups for members</li>
        </ul>
      </div>
    </section>

    <section class="framework">
      <div class="container">
        <h3>How a session is arranged</h3>
        <div class="cards">
          <div class="card">
            <h4>Entry & Care</h4>
            <p>Grounding prompts, posture cues, and breath settling to align the body’s readiness.</p>
          </div>
          <div class="card">
            <h4>Resonant Field</h4>
            <p>Layered instruments create predictable textures that shift attention without demanding it.</p>
          </div>
          <div class="card">
            <h4>Return & Integration</h4>
            <p>Clear verbal signposts to carry the session’s effects into the next hours and days.</p>
          </div>
        </div>
      </div>
    </section>

    <section class="offers" id="offers">
      <div class="container">
        <h3>Offerings</h3>
        <div class="grid">
          <article class="offer">
            <h4>Collective Circles (Membership)</h4>
            <p>Weekly small-group sessions with member-only resources and periodic intensives. Capacity-managed to preserve intimacy.</p>
            <a class="btn" href="pricing.html">Become a member</a>
          </article>
          <article class="offer">
            <h4>Focused Private Sessions</h4>
            <p>One-on-one work tailored to your nervous system and schedule. Includes a short integration plan.</p>
            <a class="btn" href="private-sessions.html">Book a private session</a>
          </article>
          <article class="offer">
            <h4>Event Series & Workshops</h4>
            <p>Occasional extended gatherings that explore instruments, sequences, and emboldened rest practices.</p>
            <a class="btn" href="events.html">See events</a>
          </article>
        </div>
      </div>
    </section>

    <section class="session-planner" id="planner">
      <div class="container">
        <h3>Session Planner</h3>
        <p class="muted">Build a short, personalized session plan you can bring to a group or use privately. Export a plaintext summary for your notes.</p>
        <form id="planner-form" aria-label="Session planner form">
          <label>Primary intention
            <select id="intent">
              <option value="calm">Calm the nervous system</option>
              <option value="sleep">Ease into sleep</option>
              <option value="focus">Find steady focus</option>
              <option value="reset">Reset after stress</option>
            </select>
          </label>

          <label>Preferred instruments
            <div class="chips">
              <label><input type="checkbox" name="instr" value="singing-bowls"> Singing bowls</label>
              <label><input type="checkbox" name="instr" value="gongs"> Gongs</label>
              <label><input type="checkbox" name="instr" value="voice"> Voice</label>
              <label><input type="checkbox" name="instr" value="flute"> Breath & flute</label>
            </div>
          </label>

          <label>Length
            <select id="length">
              <option value="30">30 minutes</option>
              <option value="60" selected>60 minutes</option>
              <option value="90">90 minutes</option>
            </select>
          </label>

          <label>Frequency
            <select id="frequency">
              <option value="once">One-off</option>
              <option value="weekly">Weekly</option>
              <option value="biweekly">Biweekly</option>
            </select>
          </label>

          <div class="form-actions">
            <button type="button" class="btn" id="build-plan">Create plan</button>
            <button type="button" class="btn ghost" id="clear-plan">Clear</button>
          </div>
        </form>

        <div class="plan-output" aria-live="polite">
          <h4>Your session summary</h4>
          <pre id="plan-text">Use the form to generate a session plan.</pre>
          <div class="output-actions">
            <button id="copy-plan" class="btn">Copy summary</button>
            <a id="download-plan" class="btn ghost" href="#" download="session-plan.txt">Download</a>
          </div>
        </div>
      </div>
    </section>

    <section class="next-events" id="next-events">
      <div class="container">
        <h3>Upcoming community gatherings</h3>
        <p class="muted">A short view of the next public sessions. For a full calendar and seat selection, visit Gatherings.</p>
        <div class="events-grid" id="events-preview">
          <article class="event-card" data-seats="12">
            <h4>Evening Resonance — Local Cohort</h4>
            <time datetime="2026-03-05T19:00">Mar 5, 7:00 pm</time>
            <p>An hour-long public session focused on stabilizing breath and receptive listening.</p>
            <div class="event-actions">
              <label>Seats to reserve
                <input type="number" min="1" max="12" value="1" class="seat-input">
              </label>
              <button class="btn reserve-btn">Reserve (simulate)</button>
              <button class="btn ghost pack-btn">What to bring</button>
            </div>
          </article>

          <article class="event-card" data-seats="8">
            <h4>Weekend Intro — Sound Structures</h4>
            <time datetime="2026-03-14T10:00">Mar 14, 10:00 am</time>
            <p>A shorter, structured introduction to getting the most from group sessions.</p>
            <div class="event-actions">
              <label>Seats to reserve
                <input type="number" min="1" max="8" value="1" class="seat-input">
              </label>
              <button class="btn reserve-btn">Reserve (simulate)</button>
              <button class="btn ghost pack-btn">What to bring</button>
            </div>
          </article>
        </div>
      </div>
    </section>

    <section class="testimonials">
      <div class="container">
        <h3>Participant notes</h3>
        <blockquote>"A practice and a pause — easier to return to than I expected." — A member in {{CITY}}</blockquote>
        <blockquote>"Clear cues and predictable sessions made rest feel like a muscle I could strengthen." — Workshop attendee</blockquote>
      </div>
    </section>

    <section class="cta-large">
      <div class="container">
        <h3>Ready to reserve a place?</h3>
        <p>Choose a plan or book a private meeting to begin a patterned approach to rest.</p>
        <div class="cta-actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn" href="book.html">Schedule a consult</a>
        </div>
      </div>
    </section>

    <section class="disclaimer">
      <div class="container">
        <h4>Contraindications & safety</h4>
        <p class="muted">Sound-based sessions may not be appropriate for everyone. If you have epilepsy, recent traumatic brain injury, certain cardiovascular conditions, or are pregnant, consult your healthcare provider before attending. Notify staff of any sensory or medical concerns in advance. Our gatherings are supportive but not a substitute for medical care.</p>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="container footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{CITY}}, {{STATE}}</p>
      </div>
      <div>
        <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
        <a href="tel:{{PHONE}}">{{PHONE}}</a>
      </div>
      <div class="small-print">
        <p>Membership & bookings: subject to terms and availability.</p>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
