{"path":"assets/css/styles.css","content":"/* Base resets */
:root{--bg:#f7f8f9;--muted:#6b7280;--accent:#2b6cb0;--dark:#0f1724;--card:#ffffff}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;line-height:1.45;color:var(--dark);background:var(--bg)}
.container{max-width:1000px;margin:0 auto;padding:2rem}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:1rem 2rem;background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);position:sticky;top:0;z-index:30;border-bottom:1px solid rgba(16,24,40,0.04)}
.brand .brand-name{margin:0;font-size:1rem;letter-spacing:0.02em}
.brand-tag{margin:0;font-size:0.85rem;color:var(--muted)}
.main-nav a{margin:0 0.5rem;color:var(--dark);text-decoration:none;font-size:0.95rem}
.cta-wrap .btn{padding:0.5rem 0.9rem;border-radius:6px;text-decoration:none}
.btn{display:inline-block;background:var(--card);border:1px solid rgba(16,24,40,0.06);padding:0.6rem 1rem;border-radius:8px;color:var(--dark);cursor:pointer;text-decoration:none}
.btn.primary{background:var(--accent);color:#fff;border:none}
.btn.ghost{background:transparent;border:1px solid rgba(16,24,40,0.06)}
.hero{padding:4rem 0;background:linear-gradient(180deg,#f3f6fb 0%,#fff 60%);position:relative;overflow:hidden}
.pattern-bg{position:absolute;inset:0;background-image:url('assets/img/pattern.svg');background-repeat:repeat;opacity:0.14}
.hero-inner{position:relative;max-width:900px;margin:0 auto;padding:3rem;text-align:left}
.hero h2{margin:0 0 1rem;font-size:2rem}
.lead{color:var(--muted);font-size:1.05rem}
.hero-actions{margin-top:1.25rem}
.story{padding:2.5rem 0}
.bullets{display:flex;gap:1rem;list-style:none;padding:0;margin:1rem 0 0}
.bullets li{background:var(--card);padding:0.8rem;border-radius:8px;flex:1}
.framework .cards{display:flex;gap:1rem}
.card{background:var(--card);padding:1rem;border-radius:10px;border:1px solid rgba(16,24,40,0.04)}
.offers .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem}
.offer{background:var(--card);padding:1rem;border-radius:10px}
.session-planner{background:rgba(43,108,176,0.04);padding:2rem 0}
.session-planner form{display:grid;gap:0.75rem;grid-template-columns:repeat(auto-fit,minmax(220px,1fr))}
.session-planner label{font-size:0.9rem}
.chips label{display:inline-flex;align-items:center;gap:0.5rem;margin-right:0.5rem}
.form-actions{grid-column:1/-1;display:flex;gap:0.5rem}
.plan-output{background:var(--card);padding:1rem;border-radius:8px;margin-top:1rem}
.plan-output pre{white-space:pre-wrap;background:transparent;border:none;margin:0;color:var(--dark)}
.next-events{padding:2rem 0}
.events-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:1rem}
.event-card{background:var(--card);padding:1rem;border-radius:10px;border:1px solid rgba(16,24,40,0.04)}
.event-actions{display:flex;gap:0.5rem;align-items:center;margin-top:0.75rem}
.event-actions input[type=number]{width:60px;padding:0.35rem}
.testimonials{padding:2rem 0}
.testimonials blockquote{background:var(--card);padding:1rem;border-left:4px solid var(--accent);margin:0 0 0.75rem;border-radius:6px}
.cta-large{background:linear-gradient(90deg,#fff,#f2f9ff);padding:2rem 0}
.disclaimer{padding:1.5rem 0;font-size:0.95rem;color:var(--muted)}
.site-footer{background:#fff;border-top:1px solid rgba(16,24,40,0.04);padding:1rem 2rem}
.footer-grid{display:flex;justify-content:space-between;align-items:center}
@media (max-width:700px){.main-nav{display:none}.brand {flex:1}}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Session Planner
  const buildBtn = document.getElementById('build-plan');
  const clearBtn = document.getElementById('clear-plan');
  const planText = document.getElementById('plan-text');
  const copyBtn = document.getElementById('copy-plan');
  const downloadBtn = document.getElementById('download-plan');

  function gatherSelections(){
    const intent = document.getElementById('intent').value;
    const length = document.getElementById('length').value;
    const frequency = document.getElementById('frequency').value;
    const instrEls = document.querySelectorAll('input[name="instr"]');
    const instruments = [];
    instrEls.forEach(i=>{ if(i.checked) instruments.push(i.parentNode.textContent.trim()); });
    return {intent,length,frequency,instruments};
  }

  function buildPlan(){
    const sel = gatherSelections();
    const timeFrames = {"30":"Quick: entry 5m, field 20m, return 5m","60":"Standard: entry 10m, field 40m, return 10m","90":"Expanded: entry 15m, field 60m, return 15m"};
    const intentNotes = {
      calm: 'Focus on breath lengthening and low-frequency sustain to encourage parasympathetic response.',
      sleep: 'Favor very slow transitions, minimal speech, and soft high-to-low tone progressions for closure.',
      focus: 'Short pulses and clear signposts help steady attention without overstimulation.',
      reset: 'Brief centring and a more textured field to interrupt rumination and invite new pacing.'
    };
    const instruments = sel.instruments.length? sel.instruments.join(', '): 'Voice + bowls (default)';
    const title = `Session Plan — intent: ${sel.intent} | ${sel.length} min | ${sel.frequency}`;
    const body = [];
    body.push(title);
    body.push('Instruments: ' + instruments);
    body.push('Structure: ' + timeFrames[sel.length]);
    body.push('Intention note: ' + (intentNotes[sel.intent]||''));
    body.push('Entry cues: settle posture; 3 rounds guided breath; ambient bell on soft pattern');
    body.push('Field work: maintain an unobtrusive loop; allow 2-3 instrument layers; avoid abrupt stops');
    body.push('Return: 2 gentle verbal markers; invite participants to note bodily changes; 1-minute silence');
    body.push('Suggested follow-up: journaling prompt or 5-minute low-energy activity');
    return body.join('\n\n');
  }

  buildBtn && buildBtn.addEventListener('click', ()=>{
    const txt = buildPlan();
    planText.textContent = txt;
    // enable download
    const blob = new Blob([txt],{type:'text/plain'});
    const url = URL.createObjectURL(blob);
    downloadBtn.href = url;
  });

  clearBtn && clearBtn.addEventListener('click', ()=>{
    document.getElementById('planner-form').reset();
    planText.textContent = 'Use the form to generate a session plan.';
  });

  copyBtn && copyBtn.addEventListener('click', async ()=>{
    const text = planText.textContent || '';
    try{
      await navigator.clipboard.writeText(text);
      copyBtn.textContent = 'Copied';
      setTimeout(()=>copyBtn.textContent = 'Copy summary',1500);
    }catch(e){
      // fallback
      const ta = document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();
      try{document.execCommand('copy');copyBtn.textContent='Copied';setTimeout(()=>copyBtn.textContent='Copy summary',1500);}catch(e){alert('Copy failed')}
      document.body.removeChild(ta);
    }
  });

  // Event seat selector & packing list generator (fake/local)
  function updateSeats(card, requested){
    const max = parseInt(card.getAttribute('data-seats')||0,10);
    const remaining = Math.max(0, max - requested);
    return {max,remaining};
  }

  document.querySelectorAll('.reserve-btn').forEach(btn=>{
    btn.addEventListener('click', (e)=>{
      const card = e.target.closest('.event-card');
      const input = card.querySelector('.seat-input');
      const requested = Number(input.value)||1;
      const info = updateSeats(card, requested);
      alert(`Simulated reservation for ${requested} seat(s). Remaining seats (simulated): ${Math.max(0, info.remaining)}.`);
    });
  });

  // Packing list generator
  function packListForEvent(card){
    // heuristics based on time and instruments
    const title = card.querySelector('h4').textContent.trim();
    const time = card.querySelector('time')? card.querySelector('time').textContent.trim():'';
    const items = ['Mat or blanket', 'Light cover', 'Water bottle', 'Soft eye pillow or scarf'];
    if(/Evening|night|sleep/i.test(title) || /pm/i.test(time)) items.push('Layered clothing for warmth');
    if(/Intro|workshop/i.test(title)) items.push('Notebook and pen');
    items.push('Optional: small cushion for vertical support');
    return {title,time,items};
  }

  document.querySelectorAll('.pack-btn').forEach(btn=>{
    btn.addEventListener('click', (e)=>{
      const card = e.target.closest('.event-card');
      const list = packListForEvent(card);
      const msg = `What to bring for "${list.title}" (${list.time}):\n\n- ` + list.items.join('\n- ');
      // show simple dialog
      if(confirm(msg + '\n\nCopy list to clipboard?')){
        try{navigator.clipboard.writeText(msg);alert('Copied to clipboard');}catch(e){alert('Unable to copy automatically');}
      }
    });
  });

})();"} 
